class Solution:
    def countPartitions(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        ans = 0
        for mask in range(1 << n):
            sa = sb = 0
            for i in range(n):
                if mask >> i & 1:
                    sb += nums[i]
                else:
                    sa += nums[i]
            if sa >= k and sb >= k:
                ans = (ans + 1) % MOD
        return ans

