class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        long long ans = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            long long sa = 0, sb = 0;
            for (int i = 0; i < n; ++i)
                (mask >> i & 1 ? sb : sa) += nums[i];
            if (sa >= k && sb >= k) ans = (ans + 1) % MOD;
        }
        return ans;
    }
};

