class Solution:
    def countPartitions(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        if sum(nums) < 2 * k:
            return 0
        dp = [0] * k
        dp[0] = 1
        for x in nums:
            for j in range(k - 1, x - 1, -1):
                dp[j] = (dp[j] + dp[j - x]) % MOD
        bad = sum(dp) % MOD
        return (pow(2, len(nums), MOD) - bad) % MOD

