class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        if (total < 2LL * k) return 0;
        vector<long long> dp(k, 0);
        dp[0] = 1;
        for (int x : nums)
            for (int j = k - 1; j >= x; --j)
                dp[j] = (dp[j] + dp[j - x]) % MOD;
        long long bad = 0;
        for (long long v : dp) bad = (bad + v) % MOD;
        long long all = 1;
        for (size_t i = 0; i < nums.size(); ++i) all = all * 2 % MOD;
        return (int)((all - bad + MOD) % MOD);
    }
};

