            for (int j = k - 1; j >= x; --j)
                dp[j] = (dp[j] + dp[j - x]) % MOD;
        long bad = 0;
        for (long v : dp) bad = (bad + v) % MOD;
        long all = 1;
        for (int i = 0; i < nums.length; ++i) all = all * 2 % MOD;
        return (int)((all - bad + MOD) % MOD);
    }
}

