var countPartitions = function(nums, k) {
    const MOD = 1e9 + 7;
    let total = nums.reduce((a, b) => a + b, 0);
    if (total < 2 * k) return 0;
    const dp = new Array(k).fill(0);
    dp[0] = 1;
    for (const x of nums)
        for (let j = k - 1; j >= x; --j)
            dp[j] = (dp[j] + dp[j - x]) % MOD;
    let bad = dp.reduce((a, b) => (a + b) % MOD, 0);
    let all = 1;
    for (let i = 0; i < nums.length; ++i) all = all * 2 % MOD;
    return ((all - bad) % MOD + MOD) % MOD;
};
